import { createItem, deleteItem, listItems, type Item } from './api';

export default function App() {
  const [items, setItems] = useState<Item[]>([]);
  const [name, setName] = useState('');
  const [error, setError] = useState('');

  const load = async () => {
    try { setItems(await listItems()); setError(''); }
    catch { setError('Could not reach the API — is the backend running on :8000?'); }
  };
  useEffect(() => { void load(); }, []);

  return (
    <main style={{ maxWidth: '40rem', margin: '6vh auto', fontFamily: 'system-ui', display: 'grid', gap: '1rem', padding: '1rem' }}>
      <h1>Items</h1>
      {error && <p role="alert">{error}</p>}
      <form onSubmit={async (event) => { event.preventDefault(); if (name.trim()) { await createItem(name.trim(), 0); setName(''); void load(); } }}>
        <input value={name} onChange={(event) => setName(event.target.value)} placeholder="New item name" />{' '}
        <button type="submit">Add item</button>
      </form>
      <ul>
        {items.map((item) => (
          <li key={item.id}>{item.name}{' '}<button type="button" onClick={async () => { await deleteItem(item.id); void load(); }}>Delete</button></li>
        ))}
      </ul>
    </main>
  );
}
